// Bundles packages/router/dashboard/* into src/dashboard-assets.generated.ts so the router (including
// the Cloudflare Worker) can serve the dashboard without file access. Run: pnpm build:dashboard
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (f) => fs.readFileSync(path.join(root, 'dashboard', f), 'utf-8');

export function renderAssetsModule() {
  return [
    '// Generated by scripts/build-dashboard.mjs from packages/router/dashboard/. Do not edit by hand.',
    `export const DASHBOARD_HTML = ${JSON.stringify(read('index.html'))};`,
    `export const DASHBOARD_CSS = ${JSON.stringify(read('app.css'))};`,
    `export const DASHBOARD_JS = ${JSON.stringify(read('app.js'))};`,
    '',
  ].join('\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  fs.writeFileSync(path.join(root, 'src', 'dashboard-assets.generated.ts'), renderAssetsModule());
  console.log('dashboard assets written to src/dashboard-assets.generated.ts');
}
